h","type":"derived","expr":"if(q_gw_p >= q_min AND q_gw_p <= q_max, 1, 0)","display":"badge","value_labels":{"0":"außerhalb Tab. 2","1":"im Bereich Tab. 2"}},{"key":"q_row","label":"Q_GW,i","type":"derived","expr":"q_gw_p * persons","unit":"l/d"}],"footer":["Q_GW_rows","greywater_type_code"],"note":"The considered sources of origin are listed in Table 2. The load values listed below serve as orientation values."}'::jsonb, NULL, NULL, NULL, (SELECT COALESCE(MAX(order_index), 0) + 1 FROM fields f3 WHERE f3.worksheet_template_id = w.id), true
