INSERT INTO fields (worksheet_template_id, section_id, symbol, label_de, data_type, unit, is_required, clause_reference, description, verification_status, verification_quote, widget, ui_config, lookup, visible_when, enum_values, order_index, active)
SELECT w.id, (SELECT ws.id FROM worksheet_sections ws WHERE ws.worksheet_template_id = w.id AND ws.code = 'B'), 'verbraucher_sw', 'Brauchwasser-Verbraucher personenbezogen (Tab. 5 → Σ Q_SW-P,i · P_i)', 'json', NULL, false, '§9.2, Eq. (1), Tab. 5', 'Plan 3: Zeilen je Anwendung (Tab. 5 Q_SW-P,i mit Begründungspflicht bei Abweichung, P_i, Nutzung nach Tab. 4); Σ → Q_SW_rows (M277E-16-D1, zusammen mit bewaesserung_sw); höchste Mindestkategorie → quality_category_code_rows (M277E-16-D2); Ablösung von Eq. (1) STAGED (m277e-R-2).', 'imported_unverified', 'The daily total service water demand $\left(\mathrm{Q}_{\mathrm{SW}}\right)$ can be calculated from the subtotals of the single application areas according to the following formula: — Q_{S W}=\Sigma\left(Q_{S W-P, i} \cdot P_{i}\right)+\Sigma\left(Q_{S W-A, j} \cdot A_{j}\right) \tag{1} — The following Table 5 provides assistance in determining the service water demand.', 'register', '{"title":"Brauchwasser-Verbraucher (personenbezogen)","subtitle":"§9.2 Tab. 5 / Eq. (1) erste Summe — je Anwendung Personen P_i und Q_SW-P,i aus Tab. 5; Nutzung nach Tab. 4 für die Mindestkategorie","add_label":"+ Verbraucher","placement":"section","columns":[{"key":"application","label":"Anwendung (Tab. 5)","type":"lookup_key","required":true,"lookup":{"table_code":"TABLE5"}},{"key":"use_category","label":"Nutzung (Tab. 4)","type":"enum","required":true,"options":["toilet_private","irrigation_lawn","irrigation_crops","laundry_private","toilet_public"],"option_labels":{"toilet_private":"Toilet flushing (private)","irrigation_lawn":"Irrigation (private) lawn, ornamental plants","irrigation_crops":"Irrigation crop plants (for consumption)","laundry_private":"Laundry (private)*","toilet_public":"Toilet flushing (public)"}},{"key":"persons","label":"P_i","type":"number","required":true,"min":0,"aria_label":"Personen dieser Anwendung"},{"key":"q_sw_p","label":"Q_SW-P,i (Tab. 5)","type":"lookup_value","unit":"l/(P·d)","lookup":{"table_code":"TABLE5","key_column":"application","value":"q_sw_p"}},{"key":"q_sw_p_override","label":"abweichend","type":"boolean"},{"key":"q_row","label":"Q_SW,i","type":"derived","expr":"q_sw_p * persons","unit":"l/d"},{"key":"min_cat","label":"Mindestkategorie (Tab. 4)","type":"derived","expr":"lookup(''TABLE4_USES'', use_category, ''min_category_code'')","display":"badge","value_labels":{"1":"C1","2":"C2"}}],"override":{"flag_key":"q_sw_p_override","applies_to":["q_sw_p"],"policy":"anhaltswert"},"footer":["Q_SW_rows","quality_category_code_rows"],"note":"The following Table 5 provides assistance in determining the service water demand."}'::jsonb, NULL, NULL, NULL, (SELECT COALESCE(MAX(order_index), 0) + 1 FROM fields f3 WHERE f3.worksheet_template_id = w.id), true
FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE NOT EXISTS (SELECT 1 FROM fields f2 WHERE f2.worksheet_template_id = w.id AND f2.symbol = 'verbraucher_sw') AND w.code = 'M277E-16' AND s.code = 'DWA-M-277E';
INSERT INTO fields (worksheet_template_id, section_id, symbol, label_de, data_type, unit, is_required, clause_reference, description, verification_status, verification_quote, widget, ui_config, lookup, visible_when, enum_values, order_index, active)
SELECT w.id, (SELECT ws.id FROM worksheet_sections ws WHERE ws.worksheet_template_id = w.id AND ws.code = 'B'), 'bewaesserung_sw', 'Bewässerungsflächen flächenbezogen (Eq. (1) → Σ Q_SW-A,j · A_j)', 'json', NULL, false, '§9.2, Eq. (1); Example calculation Part 1', 'Plan 3: Zeilen je Bewässerungsfläche (A_j, Q_SW-A,j je Saison, Saisonlänge — der Bedarf je Tag ist Q_SW-A · A / Saison wie im Beispiel §9.2; 60 l/m² und 180 d sind Beispielwerte, m277e-J-3); Σ → Q_SW_rows (M277E-16-D1); jede Bewässerung ⇒ C2 (Tab. 4).', 'imported_unverified', 'Q_{S W}=\Sigma\left(Q_{S W-P, i} \cdot P_{i}\right)+\Sigma\left(Q_{S W-A, j} \cdot A_{j}\right) \tag{1} — I Service water consumers: toilets, irrigation of kitchen garden ( $150 \mathrm{~m}^{2}$, season with 180 days) — & Q_{S W}=25 \mathrm{P} \cdot 33 \mathrm{l} /(\mathrm{P} \cdot \mathrm{~d}) \text { toilet }+60 \mathrm{l} / \mathrm{m}^{2} \cdot 150 \mathrm{~m}^{2} / 180 \mathrm{~d} \text { kitchen garden } \\', 'register', '{"title":"Bewässerungsflächen (flächenbezogen)","subtitle":"§9.2 Eq. (1) zweite Summe — je Fläche A_j und Q_SW-A,j (l/m² je Saison ÷ Saisonlänge); Beispiel §9.2: 60 l/m², 180 d","add_label":"+ Fläche","placement":"section","columns":[{"key":"label","label":"Bezeichnung","type":"text"},{"key":"use_category","label":"Nutzung (Tab. 4)","type":"enum","required":true,"options":["irrigation_lawn","irrigation_crops"],"option_labels":{"irrigation_lawn":"Irrigation (private) lawn, ornamental plants","irrigation_crops":"Irrigation crop plants (for consumption)"}},{"key":"area_m2","label":"A_j","type":"number","unit":"m²","required":true,"min":0,"aria_label":"Bewässerungsfläche"},{"key":"q_sw_a","label":"Q_SW-A,j je Saison","type":"number","unit":"l/m²","required":true,"min":0,"aria_label":"flächenspezifischer Bedarf je Saison"},{"key":"season_d","label":"Saisonlänge","type":"number","unit":"d","required":true,"min":1,"aria_label":"Saisonlänge in Tagen"},{"key":"q_sw_a_ref","label":"Beispiel §9.2 (l/m²)","type":"derived","expr":"lookup(''TABLE5_AREA'', ''kitchen_garden'', ''q_sw_a_l_m2'')","display":"badge","value_labels":{"60":"Beispiel §9.2: 60 l/m² über 180 d"}},{"key":"q_row","label":"Q_SW,j","type":"derived","expr":"q_sw_a * area_m2 / season_d","unit":"l/d"},{"key":"min_cat","label":"Mindestkategorie (Tab. 4)","type":"derived","expr":"lookup(''TABLE4_USES'', use_category, ''min_category_code'')","display":"badge","value_labels":{"1":"C1","2":"C2"}}],"footer":["Q_SW_rows"],"note":"I Service water consumers: toilets, irrigation of kitchen garden ( $150 \\mathrm{~m}^{2}$, season with 180 days)"}'::jsonb, NULL, NULL, NULL, (SELECT COALESCE(MAX(order_index), 0) + 1 FROM fields f3 WHERE f3.worksheet_template_id = w.id), true
FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE NOT EXISTS (SELECT 1 FROM fields f2 WHERE f2.worksheet_template_id = w.id AND f2.symbol = 'bewaesserung_sw') AND w.code = 'M277E-16' AND s.code = 'DWA-M-277E';
