SELECT w.id, (SELECT ws.id FROM worksheet_sections ws WHERE ws.worksheet_template_id = w.id AND ws.code = 'D'), 'Q_SW_rows', 'Σ Q_SW-P,i · P_i + Σ Q_SW-A,j · A_j über die Verbraucher-Zeilen (Eq. 1)', 'number', 'l/d', false, '§9.2, Eq. (1)', 'Plan 3: Ausgabe der Gleichung M277E-16-D1 (sum_rows über verbraucher_sw und bewaesserung_sw); Ablösung von Eq. (1) / Q_SW STAGED (m277e-R-2).', 'imported_unverified', 'Q_{S W}=\Sigma\left(Q_{S W-P, i} \cdot P_{i}\right)+\Sigma\left(Q_{S W-A, j} \cdot A_{j}\right) \tag{1}', 'derived', NULL, NULL, NULL, NULL, (SELECT COALESCE(MAX(order_index), 0) + 1 FROM fields f3 WHERE f3.worksheet_template_id = w.id), true
FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE NOT EXISTS (SELECT 1 FROM fields f2 WHERE f2.worksheet_template_id = w.id AND f2.symbol = 'Q_SW_rows') AND w.code = 'M277E-16' AND s.code = 'DWA-M-277E';
