SELECT w.id, (SELECT ws.id FROM worksheet_sections ws WHERE ws.worksheet_template_id = w.id AND ws.code = 'D'), 'quality_category_code_rows', 'Erforderliche Qualitätskategorie aus den Nutzungen als Code (1 = C1 · 2 = C2 — die höchste Anforderung entscheidet)', 'number', NULL, false, '§9.2; §6.3, Tab. 4', 'Plan 3: Ausgabe der Gleichung M277E-16-D2 (max_rows der Tab.-4-Mindestkategorie über verbraucher_sw UND bewaesserung_sw — eine Regel für beide Register); Übernahme in quality_category auf M277E-14 STAGED (m277e-D-2 / m277e-C-2).', 'imported_unverified', 'Decisive for system dimensioning is the highest quality standard. — Minimum service water quality: C2 due to the irrigation of the kitchen garden.', 'derived', NULL, NULL, NULL, NULL, (SELECT COALESCE(MAX(order_index), 0) + 1 FROM fields f3 WHERE f3.worksheet_template_id = w.id), true
