SELECT w.id, (SELECT ws.id FROM worksheet_sections ws WHERE ws.worksheet_template_id = w.id AND ws.code = 'B'), 'speicher_277', 'Speicher (vor / nach der Behandlung, Puffer) → Σ Speichervolumen', 'json', NULL, false, '§7.1; §4.2', 'Plan 3: Zeilen je Speicher (Funktion, Volumen in l); Σ / 1000 → storage_capacity_calc_m3 (M277E-21-D1); Ablösung der Skalare pre_storage_volume_l / post_storage_volume_l und des manuellen storage_capacity_m3 (M277E-01) STAGED (m277e-R-5).', 'imported_unverified', 'Depending on the type of technology used, storage of the greywater should be provided for before and/or after treatment. It is recommended that the total buffer volume corresponds to one-day treatment capacity. — According to the Building Law, the installation of a rainwater or greywater reuse system with a storage capacity up to $50 \mathrm{~m}^{3}$ usually requires a mere notification (Model Building Code: MBO 2002 § 61 Para. 5c).', 'register', '{"title":"Speicher","subtitle":"§7.1 — Speicherung vor und/oder nach der Behandlung; Puffervolumen entsprechend einer Tagesbehandlungskapazität","add_label":"+ Speicher","placement":"section","columns":[{"key":"label","label":"Bezeichnung","type":"text"},{"key":"role","label":"Funktion","type":"enum","required":true,"options":["pre","post","buffer"],"option_labels":{"pre":"vor der Behandlung (Grauwasserspeicher)","post":"nach der Behandlung (Brauchwasserspeicher)","buffer":"Puffer"}},{"key":"volume_l","label":"Volumen","type":"number","unit":"l","required":true,"min":0,"aria_label":"Speichervolumen"}],"footer":["storage_capacity_calc_m3"],"note":"Depending on the type of technology used, storage of the greywater should be provided for before and/or after treatment. It is recommended that the total buffer volume corresponds to one-day treatment capacity."}'::jsonb, NULL, NULL, NULL, (SELECT COALESCE(MAX(order_index), 0) + 1 FROM fields f3 WHERE f3.worksheet_template_id = w.id), true
