SELECT w.id, (SELECT ws.id FROM worksheet_sections ws WHERE ws.worksheet_template_id = w.id AND ws.code = 'B'), 'ablaufproben_treated', 'Ablaufproben des behandelten Grauwassers (Tab. 4 je Kategorie)', 'json', NULL, false, '§6.3, Tab. 4', 'Plan 3: Zeilen je Probe (Datum, Probenahmeort, Trübung, BOD5, O2, pH, Gesamtcoliforme, E. coli, P. aeruginosa — die C2-Parameter sind unter C1 ausgeblendet); je Zeile Vergleich mit den Tab.-4-Grenzwerten (turbidity_limit …); Anzahl Proben → treated_samples_count (M277E-24-D2), Anzahl Proben mit Verletzung → treated_samples_fail (M277E-24-D1); Gate == 0 STAGED (m277e-G-6).', 'imported_unverified', 'Quality requirements for service water should be orientated towards the specific intended use. — \hline \multirow{4}{*}{Biochemical/chemicalphysical parameters} & Turbidity & - & < 2 NTU \\ \hline & $\mathrm{BOD}_{5}$ & - & $<5 \mathrm{mg} / \mathrm{l}$ \\ \hline & O2 Saturation & > 50 \% & > 50 \% \\ \hline & pH & 6.5-9.5 & 6.5-9.5 \\ \hline \multirow{4}{*}{Hygienic parameters} & Total coliforms & \multirow[t]{3}{*}{No requirement} & $<10,000 / 100 \mathrm{ml}$ \\ \hline & E. coli & & $<1,000 / 100 \mathrm{ml}$ \\ \hline & P. aeroginosa & & $<100 / 100 \mathrm{ml}$ \\ \hline & sampling & - & Reservoir/Consumer \\', 'register', '{"title":"Ablaufproben (behandeltes Grauwasser)","subtitle":"§6.3 Tab. 4 — je Probe Ort (Speicher / Verbraucher) und Parameter; Vergleich mit den Tab.-4-Grenzwerten der Kategorie","add_label":"+ Probe","placement":"section","columns":[{"key":"date","label":"Datum","type":"date","required":true},{"key":"location","label":"Probenahme","type":"enum","required":true,"options":["reservoir","consumer"],"option_labels":{"reservoir":"Reservoir","consumer":"Consumer"}},{"key":"turbidity_ntu","label":"Trübung","type":"number","unit":"NTU","required":true,"min":0,"visible_when":"quality_category == ''C2''","aria_label":"Trübung der Probe"},{"key":"bod5","label":"BOD5","type":"number","unit":"mg/l","required":true,"min":0,"visible_when":"quality_category == ''C2''","aria_label":"BOD5 der Probe"},{"key":"o2_sat_pct","label":"O2-Sättigung","type":"number","unit":"%","required":true,"min":0,"aria_label":"O2-Sättigung der Probe"},{"key":"ph","label":"pH","type":"number","unit":"-","required":true,"min":0,"max":14,"aria_label":"pH-Wert der Probe"},{"key":"total_coliforms","label":"Gesamtcoliforme","type":"number","unit":"1/100 ml","required":true,"min":0,"visible_when":"quality_category == ''C2''","aria_label":"Gesamtcoliforme der Probe"},{"key":"e_coli","label":"E. coli","type":"number","unit":"1/100 ml","required":true,"min":0,"visible_when":"quality_category == ''C2''","aria_label":"E. coli der Probe"},{"key":"p_aeruginosa","label":"P. aeruginosa","type":"number","unit":"1/100 ml","required":true,"min":0,"visible_when":"quality_category == ''C2''","aria_label":"P. aeruginosa der Probe"},{"key":"turbidity_ok","label":"Trübung ok","type":"derived","expr":"if(quality_category == ''C2'', if(turbidity_ntu < turbidity_limit, 1, 0), 1)","display":"badge","value_labels":{"0":"überschritten","1":"ok"}},{"key":"bod5_ok","label":"BOD5 ok","type":"derived","expr":"if(quality_category == ''C2'', if(bod5 < bod5_limit, 1, 0), 1)","display":"badge","value_labels":{"0":"überschritten","1":"ok"}},{"key":"o2_ok","label":"O2 ok","type":"derived","expr":"if(o2_sat_pct > o2_sat_min, 1, 0)","display":"badge","value_labels":{"0":"unterschritten","1":"ok"}},{"key":"ph_ok","label":"pH ok","type":"derived","expr":"if(ph >= ph_min_limit AND ph <= ph_max_limit, 1, 0)","display":"badge","value_labels":{"0":"außerhalb","1":"ok"}},{"key":"total_coliforms_ok","label":"Gesamtcoliforme ok","type":"derived","expr":"if(quality_category == ''C2'', if(total_coliforms < total_coliforms_limit, 1, 0), 1)","display":"badge","value_labels":{"0":"überschritten","1":"ok"}},{"key":"e_coli_ok","label":"E. coli ok","type":"derived","expr":"if(quality_category == ''C2'', if(e_coli < e_coli_limit, 1, 0), 1)","display":"badge","value_labels":{"0":"überschritten","1":"ok"}},{"key":"p_aeruginosa_ok","label":"P. aeruginosa ok","type":"derived","expr":"if(quality_category == ''C2'', if(p_aeruginosa < p_aeruginosa_limit, 1, 0), 1)","display":"badge","value_labels":{"0":"überschritten","1":"ok"}},{"key":"sample_ok","label":"Probe","type":"derived","expr":"if(turbidity_ok == 1 AND bod5_ok == 1 AND o2_ok == 1 AND ph_ok == 1 AND total_coliforms_ok == 1 AND e_coli_ok == 1 AND p_aeruginosa_ok == 1, 1, 0)","display":"badge","value_labels":{"0":"Anforderung verletzt","1":"alle Anforderungen erfüllt"}}],"footer":["treated_samples_count","treated_samples_fail"],"note":"\\hline & sampling & - & Reservoir/Consumer \\\\"}'::jsonb, NULL, NULL, NULL, (SELECT COALESCE(MAX(order_index), 0) + 1 FROM fields f3 WHERE f3.worksheet_template_id = w.id), true
FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE NOT EXISTS (SELECT 1 FROM fields f2 WHERE f2.worksheet_template_id = w.id AND f2.symbol = 'ablaufproben_treated') AND w.code = 'M277E-24' AND s.code = 'DWA-M-277E';
