INSERT INTO fields (worksheet_template_id, section_id, symbol, label_de, data_type, unit, is_required, clause_reference, description, verification_status, verification_quote, widget, ui_config, lookup, visible_when, enum_values, order_index, active)
SELECT w.id, (SELECT ws.id FROM worksheet_sections ws WHERE ws.worksheet_template_id = w.id AND ws.code = 'B'), 'bilanzperioden', 'Bilanzperioden (Tage × Q_GW / Q_SW → Jahresvolumina)', 'json', NULL, false, '§9.4', 'Plan 3: Zeilen je Bilanzperiode (Tage, Q_GW, Q_SW; Q_WB und Q_GWT je Zeile); Σ über die Perioden → V_GW_annual, V_SW_annual, V_treated_annual, V_surplus_annual, V_topup_annual (M277E-18-D1…D5, Text-Ableitungen m277e-F-2); ersetzt Q_WB_base / Q_WB_irrig (m277e-X-2); drinking_water_savings_rate bleibt manuell (m277e-F-1).', 'imported_unverified', 'Q_{W B}=Q_{G W}-Q_{S W}=0(l / d) — As a rule, a positive water balance can be determined ( $Q_{W B}>0$ ), which means that the amount of available daily greywater inflow is higher than the demand for service water. — If a negative balance is calculated ( $Q_{W B}<0$ ), this means that the available amount of daily greywater inflow is lower than the demand for service water. — The daily treatment capacity should be complemented with data on the weekly/monthly capacity of the greywater treatment system. This dimensioning point has a decisive influence on possible upstream and downstream buffer reservoirs or it rather gives specific information on the mode of operation of the greywater reuse system.', 'register', '{"title":"Bilanzperioden","subtitle":"§9.4 — je Periode (z. B. Grundperiode / Bewässerungssaison) Tage, Q_GW und Q_SW; Q_WB = Q_GW − Q_SW, Q_GWT = min(Q_GW, Q_SW)","add_label":"+ Periode","placement":"section","columns":[{"key":"label","label":"Periode","type":"text","required":true},{"key":"days","label":"Tage","type":"number","unit":"d","required":true,"min":0,"aria_label":"Tage der Periode"},{"key":"q_gw","label":"Q_GW","type":"number","unit":"l/d","required":true,"min":0,"aria_label":"Grauwasseranfall der Periode"},{"key":"q_sw","label":"Q_SW","type":"number","unit":"l/d","required":true,"min":0,"aria_label":"Brauchwasserbedarf der Periode"},{"key":"q_wb","label":"Q_WB","type":"derived","expr":"q_gw - q_sw","unit":"l/d"},{"key":"q_gwt","label":"Q_GWT","type":"derived","expr":"min(q_gw, q_sw)","unit":"l/d"},{"key":"balance","label":"Bilanz","type":"derived","expr":"if(q_wb > 0, 1, if(q_wb < 0, -1, 0))","display":"badge","value_labels":{"0":"ausgeglichen","1":"Überschuss (Q_WB > 0)","-1":"Defizit (Q_WB < 0)"}}],"footer":["V_GW_annual","V_SW_annual","V_treated_annual","V_surplus_annual","V_topup_annual"],"note":"The daily treatment capacity should be complemented with data on the weekly/monthly capacity of the greywater treatment system. This dimensioning point has a decisive influence on possible upstream and downstream buffer reservoirs or it rather gives specific information on the mode of operation of the greywater reuse system."}'::jsonb, NULL, NULL, NULL, (SELECT COALESCE(MAX(order_index), 0) + 1 FROM fields f3 WHERE f3.worksheet_template_id = w.id), true
FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE NOT EXISTS (SELECT 1 FROM fields f2 WHERE f2.worksheet_template_id = w.id AND f2.symbol = 'bilanzperioden') AND w.code = 'M277E-18' AND s.code = 'DWA-M-277E';
COMMIT;
